-- U11 (T-104, release 1), forward-only. The two partial unique indexes are generated by drizzle-kit
-- from `schema/identity.ts` (BR2.4, BR2.6); the deferrable key below is hand-written, because
-- Drizzle 0.45 has no deferrable foreign keys (the `0004_deferred_fks.sql` precedent). No grant
-- changes: `0001_grants_part1.sql` already revokes `persona_links` from rk_worker (BR3.7).
CREATE UNIQUE INDEX "persona_links_account_review_uq" ON "persona_links" USING btree ("account_id","review_id") WHERE "persona_links"."review_id" IS NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "personas_anonymous_alias_uq" ON "personas" USING btree ("display_name") WHERE "personas"."kind" = 'anonymous' AND "personas"."display_name" LIKE 'patient-%';--> statement-breakpoint
-- BR2.9: an anonymous persona and its link are written before the review they name, in the same
-- transaction (`review.publish` calls `personaFor`, then inserts the review). ON DELETE SET NULL kept.
ALTER TABLE persona_links DROP CONSTRAINT persona_links_review_id_reviews_id_fk;--> statement-breakpoint
ALTER TABLE persona_links
  ADD CONSTRAINT persona_links_review_id_reviews_id_fk
  FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE SET NULL
  DEFERRABLE INITIALLY DEFERRED;
